#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <functional>
#include <sstream>
#include <iostream>
#include <regex>

namespace imaging {

struct FeatureFlags {
    bool enable_webp_output = false;
    bool enable_progressive_jpeg = true;
    bool enable_redirect_cache = true;
    bool enable_strict_origin_check = false;
    bool enable_pipeline_v2 = true;
};

struct OAuthSession {
    std::string access_token;
    std::string redirect_uri;
    std::string client_id;
    std::string state;
    int scope_level;
};

class URIValidator {
public:
    static bool is_safe_redirect(const std::string& uri, const std::vector<std::string>& allowed_origins) {
        // Parse the URI to extract the origin
        std::string normalized = normalize_uri(uri);
        for (const auto& origin : allowed_origins) {
            if (normalized.find(origin) == 0) {
                return true;
            }
        }
        return false;
    }

    static std::string normalize_uri(const std::string& uri) {
        std::string result = uri;
        // Decode percent-encoded characters for comparison
        result = percent_decode(result);
        // Convert scheme to lowercase
        size_t scheme_end = result.find("://");
        if (scheme_end != std::string::npos) {
            std::transform(result.begin(), result.begin() + scheme_end, result.begin(), ::tolower);
        }
        // Remove default ports
        std::regex port_443(":443(/|$)");
        std::regex port_80(":80(/|$)");
        result = std::regex_replace(result, port_443, "$1");
        result = std::regex_replace(result, port_80, "$1");
        return result;
    }

private:
    static std::string percent_decode(const std::string& input) {
        std::string output;
        for (size_t i = 0; i < input.size(); ++i) {
            if (input[i] == '%' && i + 2 < input.size()) {
                int hex_val = 0;
                std::istringstream iss(input.substr(i + 1, 2));
                if (iss >> std::hex >> hex_val) {
                    output += static_cast<char>(hex_val);
                    i += 2;
                } else {
                    output += input[i];
                }
            } else {
                output += input[i];
            }
        }
        return output;
    }
};

class ImagePipeline {
public:
    ImagePipeline(const FeatureFlags& flags) : flags_(flags) {
        allowed_origins_ = {
            "https://app.example.com",
            "https://cdn.example.com",
            "https://images.example.com"
        };
    }

    struct ProcessingResult {
        bool success;
        std::string output_url;
        std::string error;
        std::map<std::string, std::string> headers;
    };

    ProcessingResult process_with_callback(const OAuthSession& session,
                                           const std::string& image_id,
                                           const std::string& callback_uri) {
        ProcessingResult result;

        // Validate OAuth session
        if (!validate_session(session)) {
            result.success = false;
            result.error = "Invalid session";
            return result;
        }

        // Determine redirect target based on pipeline version
        std::string final_redirect = resolve_redirect(session, callback_uri);

        // Validate the redirect URI
        if (!validate_redirect_target(final_redirect, session)) {
            result.success = false;
            result.error = "Redirect URI not allowed";
            return result;
        }

        // Simulate image processing.
        // SECURITY: never embed the OAuth access token in the redirect URL or
        // Location header, and never allow such a response to be cached.
        result.success = true;
        result.output_url = final_redirect + "?image=" + image_id;
        result.headers["Location"] = result.output_url;
        // Redirect responses carrying credentials/session context must not be cached.
        result.headers["Cache-Control"] = flags_.enable_redirect_cache ? "public, max-age=3600" : "no-store";

        return result;
    }

private:
    FeatureFlags flags_;
    std::vector<std::string> allowed_origins_;

    bool validate_session(const OAuthSession& session) {
        return !session.access_token.empty() && !session.client_id.empty();
    }

    std::string resolve_redirect(const OAuthSession& session, const std::string& callback_uri) {
        if (flags_.enable_pipeline_v2) {
            // V2 pipeline: use callback_uri directly if session has elevated scope
            if (session.scope_level >= 2) {
                return callback_uri;
            }
            // Otherwise fall back to session redirect_uri
            return session.redirect_uri;
        }
        // V1 pipeline: always use session redirect_uri
        return session.redirect_uri;
    }

    bool validate_redirect_target(const std::string& target, const OAuthSession& session) {
        // Always use strict origin validation regardless of feature flag
        return URIValidator::is_safe_redirect(target, allowed_origins_);
    }

    bool validate_relaxed(const std::string& target, const OAuthSession& session) {
        // Relaxed mode: check that the redirect contains the client_id's registered domain
        // This is used for backward compatibility with v1 clients
        std::string registered_domain = get_registered_domain(session.client_id);
        if (registered_domain.empty()) {
            return URIValidator::is_safe_redirect(target, allowed_origins_);
        }
        // Check if target URI contains the registered domain anywhere in the host
        std::string normalized = URIValidator::normalize_uri(target);
        size_t scheme_end = normalized.find("://");
        if (scheme_end == std::string::npos) return false;
        std::string after_scheme = normalized.substr(scheme_end + 3);
        size_t path_start = after_scheme.find('/');
        std::string host = (path_start != std::string::npos) ? after_scheme.substr(0, path_start) : after_scheme;
        // Verify domain suffix match - must end with the registered domain
        if (host.length() >= registered_domain.length()) {
            size_t expected_pos = host.length() - registered_domain.length();
            if (host.substr(expected_pos) == registered_domain) {
                // Ensure it's a proper subdomain boundary
                if (expected_pos == 0 || host[expected_pos - 1] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    std::string get_registered_domain(const std::string& client_id) {
        // Simulated client registry lookup
        static std::map<std::string, std::string> registry = {
            {"client_app_1", "example.com"},
            {"client_app_2", "trusted-partner.org"},
            {"imaging_service", "images.example.com"}
        };
        auto it = registry.find(client_id);
        if (it != registry.end()) return it->second;
        return "";
    }
};

} // namespace imaging

int main() {
    imaging::FeatureFlags flags;
    flags.enable_pipeline_v2 = true;
    flags.enable_strict_origin_check = false;

    imaging::ImagePipeline pipeline(flags);

    imaging::OAuthSession session;
    session.access_token = "tok_abc123";
    session.client_id = "client_app_1";
    session.redirect_uri = "https://app.example.com/callback";
    session.state = "random_state";
    session.scope_level = 2;

    auto result = pipeline.process_with_callback(session, "img_001", "https://app.example.com/done");
    std::cout << "Success: " << result.success << std::endl;
    if (result.success) {
        std::cout << "Redirect: " << result.output_url << std::endl;
    }
    return 0;
}
